<template>
  <div class="nw-site nw-demo-site"><a class="nw-skip" href="#nw-demo-main">Skip to demo</a><header class="nw-header nw-wrap"><router-link to="/fundthred/noteworthy" aria-label="NoteWorthy Payroll home"><NoteworthyBrand/></router-link><div class="nw-demo-header-actions"><router-link class="nw-text-link" to="/fundthred/noteworthy">← Product overview</router-link><router-link class="nw-button" to="/fundthred/noteworthy/start">Create your practice <NoteworthyIcon name="arrow"/></router-link></div></header><div class="nw-demo-disclaimer"><NoteworthyIcon name="shield"/><span><strong>An interactive demo, with fictional data.</strong> No real reports, employee information, emails, or payroll transactions.</span></div>
    <main id="nw-demo-main" class="nw-wrap nw-demo-main" tabindex="-1"><div class="nw-demo-heading"><div><p class="nw-eyebrow">EVERGREEN THERAPY · FICTIONAL PRACTICE</p><h1>{{ providerView?'The provider portal.':'Meet your next payday.' }}</h1><p>{{ providerView?'A simple answer to what was paid, when, and why.':'Walk through the same decisions, from a billing report to a clear payroll handoff.' }}</p></div><div class="nw-view-switch" role="group" aria-label="Choose a portal view"><button :aria-pressed="!providerView" @click="providerView=false">Payroll team</button><button :aria-pressed="providerView" @click="openProviderView">Provider portal</button></div></div>
      <template v-if="!providerView"><div class="nw-demo-layout"><aside class="nw-demo-nav"><h2>Payroll wizard</h2><p>Oct 24 – Nov 6, 2026</p><ol><li v-for="(phase,i) in demoPhases" :key="phase"><button :class="{active:step.phase===i,complete:phaseComplete(i)}" :disabled="phaseStart(i)>furthest" @click="goStep(phaseStart(i))"><span>{{ phaseComplete(i)?'✓':i+1 }}</span><strong>{{ phase }}</strong><NoteworthyIcon v-if="step.phase===i" name="arrow"/></button></li></ol><div class="nw-demo-nav-bottom"><span class="nw-iconbox mint"><NoteworthyIcon name="shield"/></span><p>Decisions stay connected.<br><strong>So does the evidence.</strong></p><button class="nw-text-link" @click="resetDemo">Restart demo ↺</button></div></aside>
        <section class="nw-demo-workspace"><div class="nw-demo-progress"><span>Step {{ index+1 }} of {{ demoSteps.length }}</span><div role="progressbar" :aria-valuenow="index+1" :aria-valuemin="1" :aria-valuemax="demoSteps.length" :aria-label="`Payroll walkthrough progress: step ${index+1} of ${demoSteps.length}`"><span :style="{width:`${((index+1)/demoSteps.length)*100}%`}"></span></div><span>{{ demoPhases[step.phase] }}</span></div><div class="nw-demo-step-chips" v-if="phaseSteps.length>1"><button v-for="item in phaseSteps" :key="item.id" :class="{active:item.id===step.id,complete:completed.has(item.id)}" :disabled="demoSteps.indexOf(item)>furthest" @click="goStep(demoSteps.indexOf(item))">{{ completed.has(item.id)?'✓ ':'' }}{{ shortStep(item.id) }}</button></div><header class="nw-demo-step-heading"><p class="nw-eyebrow">{{ demoPhases[step.phase] }}</p><h2 ref="stepHeading" tabindex="-1">{{ step.title }}</h2><p>{{ step.description }}</p></header>
          <div class="nw-demo-step-body">
            <template v-if="step.id==='upload'"><div class="nw-demo-upload"><span class="nw-iconbox mint"><NoteworthyIcon name="upload"/></span><h3>{{ state.loaded?'Your sample report is ready.':'One report. A smarter starting point.' }}</h3><p>TherapyNotes billing report<br><strong>October 24 – November 6, 2026</strong></p><button class="nw-button" @click="loadSample" :disabled="state.loaded" data-test="load-sample">{{ state.loaded?'✓ Sample report loaded':'Load fictional billing report' }}<NoteworthyIcon v-if="!state.loaded" name="arrow"/></button><small>This public demo does not accept uploads.<br>Use the signed-in practice workspace for real reports.</small></div><div v-if="state.loaded" class="nw-demo-import-result" role="status"><span class="nw-iconbox mint"><NoteworthyIcon name="people"/></span><div><strong>4 providers found. Your team is taking shape.</strong><p>Review each provider’s compensation before your first payroll.</p></div></div><div v-if="state.loaded" class="nw-demo-provider-grid"><article v-for="p in demoProviders" :key="p.id"><span class="nw-avatar" :class="p.color">{{ p.initials }}</span><strong>{{ p.name }}</strong><span>{{ p.credential }} · {{ money(state.rates[p.id]) }} sample session rate</span></article></div></template>
            <template v-else-if="['prior','draft'].includes(step.id)"><div class="nw-demo-decision-intro"><span class="nw-badge" :class="decision?'nw-badge--mint':'nw-badge--gold'">{{ decision?'Decision saved':'1 draft needs a decision' }}</span><span>The choice belongs to your payroll team.</span></div><div class="nw-demo-table-wrap"><table><caption class="nw-sr-only">{{ step.id==='prior'?'Prior period draft':'Current period draft' }}</caption><thead><tr><th>Provider / service</th><th>Service date</th><th>Note</th><th>Pay decision</th></tr></thead><tbody><tr><td><strong>{{ step.id==='prior'?'Taylor Gomez':'Morgan Ellis' }}</strong><small>90837 · Individual therapy</small></td><td>{{ step.id==='prior'?'Oct 23, 2026':'Nov 6, 2026' }}</td><td><span class="nw-badge nw-badge--gold">Draft</span></td><td><div class="nw-inline-actions"><button class="nw-button nw-button--small" :aria-pressed="decision==='payable'" @click="setDecision('payable')" data-test="draft-payable">{{ decision==='payable'?'✓ Payable':'Mark payable' }}</button><button class="nw-button nw-button--small nw-button--outline" :aria-pressed="decision==='unpaid'" @click="setDecision('unpaid')" data-test="draft-unpaid">{{ decision==='unpaid'?'✓ Keep unpaid':'Keep unpaid' }}</button></div></td></tr></tbody></table></div><p class="nw-demo-explanation">{{ decision==='unpaid'?'The draft stays unpaid and visible for a later review.':decision==='payable'?'This draft is included in the sample payroll calculation.':'A draft status and a payment decision are separate. Decide what is ready to pay under your practice policy.' }}</p></template>
            <template v-else-if="step.id==='late'"><div class="nw-demo-difference"><span class="nw-iconbox purple"><NoteworthyIcon name="clock"/></span><div><span class="nw-eyebrow">FOUND SINCE LAST PAYROLL</span><h3>Jordan finished a late note.</h3><p>October 22, 2026 · 90837 · Individual therapy</p><div class="nw-demo-from-to"><span class="nw-badge nw-badge--gold">No note · unpaid</span><NoteworthyIcon name="arrow"/><span class="nw-badge nw-badge--mint">Finalized · ready to add</span></div></div><strong>{{ money(state.rates.jordan) }}</strong></div><button class="nw-button" :disabled="state.lateAdded" @click="state.lateAdded=true;invalidateCalculation()" data-test="add-late">{{ state.lateAdded?'✓ Added to this payroll':'Add late note to this payroll' }}<NoteworthyIcon v-if="!state.lateAdded" name="arrow"/></button><p class="nw-demo-explanation">{{ state.lateAdded?'Added once, with the original date of service. You’ll see it on Jordan’s statement.':'The note was missing from the earlier payroll. A finalized note now gives you something concrete to review.' }}</p><div class="nw-demo-correction"><div class="nw-demo-correction-heading"><span class="nw-iconbox gold"><NoteworthyIcon name="alert"/></span><div><span class="nw-eyebrow">A PAY CHANGE WORTH A CLOSER LOOK</span><h3>Morgan’s service code changed.</h3><p>October 21 · 90837 → Pro bono</p></div><button class="nw-button nw-button--small nw-button--outline" :aria-expanded="showCorrection" @click="showCorrection=!showCorrection" data-test="review-correction">{{ showCorrection?'Hide details':'Review code change' }}</button></div><div v-if="showCorrection" class="nw-demo-correction-details"><p>The earlier sample payroll paid $38.00 for this session on October 29. The corrected report now identifies the visit as pro bono, which pays $0.00.</p><dl><div><dt>Previously paid</dt><dd>$38.00</dd></div><div><dt>Corrected service pay</dt><dd>$0.00</dd></div><div><dt>Sample difference</dt><dd>−$38.00</dd></div></dl><button class="nw-button nw-button--small" :disabled="state.correctionApplied" @click="state.correctionApplied=true;invalidateCalculation()" data-test="apply-correction">{{ state.correctionApplied?'✓ Separate correction line added':'Apply sample reduction' }}</button><p class="nw-demo-explanation">Illustrative review only. Real corrections require saved payment evidence, authorized payroll review, and your practice’s applicable recovery process.</p></div></div></template>
            <template v-else-if="step.id==='h0031'"><div class="nw-demo-service-review"><span class="nw-iconbox blue"><NoteworthyIcon name="document"/></span><div><h3>Taylor Gomez · H0031</h3><p>November 5, 2026 · Assessment · Finalized</p></div><label>Reviewed units<input type="number" min="1" max="60" step="1" v-model.number="assessmentUnits" :disabled="state.assessmentReviewed"/></label></div><p>For this sample rule, 60 minutes is one pay credit at {{ money(state.rates.taylor) }}.</p><button class="nw-button" @click="state.assessmentReviewed=true" :disabled="state.assessmentReviewed||assessmentUnits!==60" data-test="confirm-assessment">{{ state.assessmentReviewed?'✓ Units confirmed':'Confirm 60 sample units' }}</button><p v-if="assessmentUnits!==60" class="nw-demo-explanation">This walkthrough uses the sample report’s 60-minute assessment. Set units to 60 to confirm.</p></template>
            <template v-else-if="['h2014','90853'].includes(step.id)"><div class="nw-demo-service-review"><span class="nw-iconbox blue"><NoteworthyIcon name="layers"/></span><div><h3>Casey Kim · {{ step.id.toUpperCase() }}</h3><p>{{ step.id==='h2014'?'24 quarter-hour units · 6 pay credits':'2 group pay credits' }}</p></div><strong>{{ money(state.rates.casey*(step.id==='h2014'?6:2)) }}</strong></div><div class="nw-demo-saved-note"><NoteworthyIcon name="check"/> Sample service rule applied. No changes need your attention.</div></template>
            <template v-else-if="step.id==='claims'"><div class="nw-demo-toolbar"><label><input type="checkbox" :checked="selectedClaims.length===2" @change="selectedClaims=$event.target.checked?['jordan','taylor']:[]" :disabled="state.claimsApproved"/> Select all sample claims</label><button class="nw-button nw-button--small" @click="approveClaims" :disabled="state.claimsApproved||selectedClaims.length!==2" data-test="approve-claims">{{ state.claimsApproved?'✓ 2 claims approved':'Approve selected (2)' }}</button></div><div class="nw-demo-table-wrap"><table><caption class="nw-sr-only">Sample administrative time claims</caption><thead><tr><th>Select</th><th>Provider</th><th>Activity</th><th>Hours</th><th>Pay</th></tr></thead><tbody><tr v-for="id in ['jordan','taylor']" :key="id"><td><input type="checkbox" :value="id" v-model="selectedClaims" :disabled="state.claimsApproved" :aria-label="`Select ${providerById(id).name} claim`"/></td><td><strong>{{ providerById(id).name }}</strong></td><td>Administrative time<small>50% of sample session rate</small></td><td>{{ id==='jordan'?'1.5':'1.0' }}</td><td><strong>{{ money(state.rates[id]*.5*(id==='jordan'?1.5:1)) }}</strong></td></tr></tbody></table></div><p class="nw-demo-explanation">This demo approves both sample claims together. Real claims follow the activities and rates assigned by your practice.</p></template>
            <template v-else-if="step.id==='stage'"><div class="nw-demo-table-wrap"><table><caption class="nw-sr-only">Editable fictional provider compensation rates</caption><thead><tr><th>Provider</th><th>Credential</th><th>Sample session rate</th><th>Calculated service pay</th></tr></thead><tbody><tr v-for="p in demoProviders" :key="p.id"><td><strong>{{ p.name }}</strong></td><td>{{ p.credential }}</td><td><label class="nw-rate-field"><span aria-hidden="true">$</span><input type="number" min="0" max="500" step="1" :aria-label="`${p.name} sample rate`" :value="state.rates[p.id]" @input="setRate(p.id,$event.target.value)"/></label></td><td><strong>{{ money(providerTotal(state,p.id)) }}</strong></td></tr></tbody></table></div><div class="nw-demo-saved-note"><NoteworthyIcon name="shield"/> Morgan’s pro bono session remains $0.00, regardless of rate changes.</div><p class="nw-demo-explanation">These sample compensation rules are illustrative. Your real practice configures rates by provider, service code, credential, and applicable policy.</p></template>
            <template v-else-if="step.id==='compliance'"><div class="nw-demo-difference"><span class="nw-iconbox gold"><NoteworthyIcon name="document"/></span><div><span class="nw-eyebrow">STILL NEEDS A NOTE</span><h3>Morgan Ellis · November 4</h3><p>90837 · Missing note · No session pay included</p></div><span class="nw-badge nw-badge--gold">Unpaid</span></div><p>The missing note stays visible for follow-up and future catch-up. It is separate from the draft payment decision you already reviewed.</p><button class="nw-button nw-button--outline" :aria-expanded="showEmail" @click="showEmail=!showEmail">{{ showEmail?'Hide':'Preview' }} reminder</button><div v-if="showEmail" class="nw-demo-email"><span class="nw-eyebrow">DEMO EMAIL PREVIEW · NOTHING IS SENT</span><h3>A quick note before payday</h3><p>Hi Morgan,</p><p>Your November 4 session is still missing a note. It is not included in the current payroll. When the note is ready, payroll can review it in a later catch-up.</p></div></template>
            <template v-else-if="step.id==='run'"><div class="nw-demo-calculation"><span class="nw-iconbox mint"><NoteworthyIcon name="check"/></span><p>{{ state.calculated?'Your sample calculation is ready.':'Reviewed work. Clear rules. Ready to calculate.' }}</p><strong>{{ money(total) }}</strong><span>4 providers · Gross service pay before deductions</span><button class="nw-button" @click="state.calculated=true" :disabled="state.calculated" data-test="calculate">{{ state.calculated?'✓ Demo payroll calculated':'Calculate demo payroll' }}<NoteworthyIcon v-if="!state.calculated" name="arrow"/></button></div></template>
            <template v-else-if="step.id==='preview'"><div class="nw-demo-table-wrap"><table><caption class="nw-sr-only">Fictional payroll preview by provider</caption><thead><tr><th>Provider</th><th>Credential</th><th>Gross service pay</th><th>Details</th></tr></thead><tbody><tr v-for="p in demoProviders" :key="p.id"><td><strong>{{ p.name }}</strong></td><td>{{ p.credential }}</td><td><strong>{{ money(providerTotal(state,p.id)) }}</strong></td><td><button class="nw-button nw-button--small nw-button--outline" @click="selectedProvider=p.id;providerView=true">View statement →</button></td></tr></tbody></table></div><p class="nw-demo-explanation">Open any statement. You can return to this exact step after seeing the provider view.</p></template>
            <template v-else-if="step.id==='post'"><div class="nw-demo-calculation"><span class="nw-iconbox mint"><NoteworthyIcon :name="state.posted?'check':'download'"/></span><p>{{ state.posted?'Demo payroll posted. Every statement has a story.':'One clear handoff. Your payroll system stays.' }}</p><strong>{{ money(total) }}</strong><span>{{ state.posted?'Simulated publish · no real payroll was processed':'Reviewed gross service pay · 4 fictional providers' }}</span><button v-if="!state.posted" class="nw-button" @click="state.posted=true" data-test="post-demo">Post demo payroll <NoteworthyIcon name="arrow"/></button><div v-else class="nw-actions"><button class="nw-button" @click="downloadCsv" data-test="download-csv"><NoteworthyIcon name="download"/> Download sample CSV</button><button class="nw-button nw-button--outline" @click="providerView=true">See provider portal →</button></div><p v-if="downloaded" role="status">Sample CSV downloaded. It contains fictional data only.</p></div><p class="nw-demo-explanation">NoteWorthy prepares and reconciles pay. Your payroll provider handles the actual payments, withholding, and tax filings. The sample CSV is an illustration of the handoff, not a live processor import.</p></template>
            <template v-else><div class="nw-demo-empty"><span class="nw-iconbox mint"><NoteworthyIcon name="check"/></span><h3>{{ step.id==='two-ago'?'No prior drafts need a decision.':step.id==='fees'?'No missed appointment fees to review.':`No ${step.id.toUpperCase()} items need your attention.` }}</h3><p>The wizard checked the sample report. You can continue directly to the next step.</p><span class="nw-badge nw-badge--mint">Nothing to handle here</span></div></template>
          </div><div v-if="blocker" class="nw-demo-blocker" role="status"><NoteworthyIcon name="alert"/><span>{{ blocker }}</span></div><footer class="nw-demo-controls"><button class="nw-button nw-button--outline" @click="goStep(index-1)" :disabled="index===0">← Back</button><span>{{ state.loaded?`${money(total)} · demo gross pay`:'Fictional data only' }}</span><button v-if="index<demoSteps.length-1" class="nw-button" @click="nextStep" :disabled="!!blocker" data-test="continue">Continue <NoteworthyIcon name="arrow"/></button><router-link v-else-if="state.posted" class="nw-button" to="/fundthred/noteworthy/start">Start with your practice <NoteworthyIcon name="arrow"/></router-link></footer>
        </section></div>
      </template>
      <section v-else class="nw-demo-provider-portal"><div class="nw-demo-provider-sidebar"><NoteworthyBrand/><p class="nw-eyebrow">YOUR PROVIDER PORTAL</p><label for="nw-demo-provider">Preview as</label><select id="nw-demo-provider" v-model="selectedProvider"><option v-for="p in demoProviders" :key="p.id" :value="p.id">{{ p.name }} · {{ p.credential }}</option></select><p>Fictional provider access. Each real provider sees their own authorized payroll information.</p><button class="nw-button nw-button--outline" @click="providerView=false">← Back to the wizard</button></div><article class="nw-demo-paystub"><header><span class="nw-avatar" :class="activeProvider.color">{{ activeProvider.initials }}</span><div><p class="nw-eyebrow">HELLO, {{ activeProvider.name.split(' ')[0].toUpperCase() }}.</p><h2>Your pay, explained.</h2></div><span class="nw-badge nw-badge--mint">{{ state.posted?'Demo posted':'Sample preview' }}</span></header><div class="nw-demo-paystub-total"><span>October 24 – November 6, 2026</span><strong data-test="provider-total">{{ money(providerTotal(providerState,selectedProvider)) }}</strong><p>Gross service pay · before taxes and deductions</p></div><div class="nw-demo-table-wrap"><table><caption>What’s included in this pay</caption><thead><tr><th>Work / original date</th><th>Code</th><th>Credits / hours</th><th>Rate</th><th>Pay</th></tr></thead><tbody><tr v-for="line in demoLines(providerState,selectedProvider)" :key="line.id"><td><strong>{{ line.label }}</strong><small>{{ line.date }}<span v-if="line.late"> · Prior-period catch-up</span></small></td><td>{{ line.code }}</td><td>{{ line.quantity }}</td><td>{{ money(line.rate) }}</td><td><strong>{{ money(line.amount) }}</strong></td></tr></tbody><tfoot><tr><th colspan="4">Gross service pay</th><td><strong>{{ money(providerTotal(providerState,selectedProvider)) }}</strong></td></tr></tfoot></table></div><p class="nw-demo-explanation">This shows what the sample compensation rules produced. Your payroll provider supplies the final payment, tax deductions, and official pay stub.</p></article></section>
    </main><footer class="nw-demo-footer nw-wrap"><span><NoteworthyIcon name="shield"/> NoteWorthy Payroll by FundThred · Built on Auricwell</span><router-link to="/fundthred/noteworthy/start">Ready for your own practice? Get started →</router-link></footer>
  </div>
</template>
<script setup>
import { computed, nextTick, reactive, ref } from 'vue';
import { useRoute } from 'vue-router';
import NoteworthyBrand from '../../components/noteworthy/NoteworthyBrand.vue';
import NoteworthyIcon from '../../components/noteworthy/NoteworthyIcon.vue';
import { createDemoState, demoBlocker, demoCsv, demoLines, demoPhases, demoProviders, demoSteps, demoTotal, money, providerTotal } from '../../content/noteworthyPayroll';
import { useNoteworthyMetadata } from '../../composables/useNoteworthyMetadata';
import '../../styles/noteworthyPayroll.css';
useNoteworthyMetadata({ title: 'Try NoteWorthy Payroll | Guided demo by FundThred', description: 'Explore a fictional therapy practice from billing report through the payroll wizard, provider statements, and payroll reconciliation export.', path: '/noteworthy/demo' });
const route=useRoute();
const state=reactive(createDemoState()),index=ref(0),furthest=ref(0),completed=reactive(new Set());
const providerView=ref(route.query.view==='provider'),selectedProvider=ref('jordan'),selectedClaims=ref(['jordan','taylor']),assessmentUnits=ref(60),showEmail=ref(false),showCorrection=ref(false),downloaded=ref(false),stepHeading=ref(null);
const step=computed(()=>demoSteps[index.value]),phaseSteps=computed(()=>demoSteps.filter(item=>item.phase===step.value.phase));
const blocker=computed(()=>demoBlocker(step.value.id,state)),total=computed(()=>demoTotal(state));
const decision=computed(()=>step.value.id==='prior'?state.priorDecision:state.draftDecision);
const activeProvider=computed(()=>providerById(selectedProvider.value));
const providerState=computed(()=>state.loaded?state:{...createDemoState(),loaded:true,priorDecision:'payable',lateAdded:true,draftDecision:'payable',claimsApproved:true});
function providerById(id){return demoProviders.find(p=>p.id===id)||demoProviders[0];}
function phaseStart(phase){return demoSteps.findIndex(item=>item.phase===phase);}
function phaseComplete(phase){return demoSteps.filter(item=>item.phase===phase).every(item=>completed.has(item.id));}
function shortStep(id){return ({prior:'Prior period', 'two-ago':'Two periods ago',late:'Late notes',draft:'Drafts',fees:'Missed fees',h0031:'H0031',h0032:'H0032',h2014:'H2014','90853':'90853',h2032:'H2032',claims:'Time claims',stage:'Pay rules',run:'Calculate',preview:'Preview',post:'Post'})[id]||id;}
function goStep(next){if(next<0||next>=demoSteps.length||next>furthest.value)return;index.value=next;nextTick(()=>{stepHeading.value?.focus({preventScroll:true});stepHeading.value?.closest('.nw-demo-workspace')?.scrollIntoView?.({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches?'instant':'smooth'});});}
function nextStep(){if(blocker.value)return;completed.add(step.value.id);furthest.value=Math.max(furthest.value,index.value+1);goStep(index.value+1);}
function loadSample(){state.loaded=true;}
function invalidateCalculation(){state.calculated=false;state.posted=false;for(const id of ['run','preview','post'])completed.delete(id);}
function setDecision(value){if(step.value.id==='prior')state.priorDecision=value;else state.draftDecision=value;invalidateCalculation();}
function approveClaims(){if(selectedClaims.value.length===2){state.claimsApproved=true;invalidateCalculation();}}
function setRate(id,value){const numeric=Number(value);if(Number.isFinite(numeric)&&numeric>=0&&numeric<=500){state.rates[id]=numeric;invalidateCalculation();}}
function openProviderView(){providerView.value=true;}
function resetDemo(){Object.assign(state,createDemoState());index.value=0;furthest.value=0;completed.clear();selectedClaims.value=['jordan','taylor'];assessmentUnits.value=60;downloaded.value=false;showEmail.value=false;showCorrection.value=false;}
function downloadCsv(){const url=URL.createObjectURL(new Blob([demoCsv(state)],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='NoteWorthy-DEMO-fictional-payroll.csv';link.click();downloaded.value=true;setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
